// Health-check des services JARVIS (network=host -> 127.0.0.1). Secret-safe.
const services = [
  {name:'LLM hub 18800', url:'http://127.0.0.1:18800/v1/models'},
  {name:'LM Studio 1234', url:'http://127.0.0.1:1234/v1/models'},
  {name:'Antigravity 9011', url:'http://127.0.0.1:9011/json/version'},
  {name:'Dashboard 18801', url:'http://127.0.0.1:18801/'},
  {name:'CCR 18802', url:'http://127.0.0.1:18802/'},
  {name:'Orchestrateur 9742', url:'http://127.0.0.1:9742/'},
  {name:'n8n 5678', url:'http://127.0.0.1:5678/healthz'},
];
const down = [];
for (const s of services) {
  try { await this.helpers.httpRequest({url:s.url, timeout:3000}); }
  catch(e) { down.push(s.name); }
}
return [{json:{down, count:down.length, msg: down.length? ('\u26a0\ufe0f JARVIS services DOWN: '+down.join(', ')) : 'ok'}}];
